import re
from typing import List, Dict, Any, Tuple, Union

# ------------------------------------------------------------------
# Helper stubs (provided by the environment, assumed to work)
# ------------------------------------------------------------------
# def node_by_title(doc: dict, title: str) -> dict | None
# def node_by_id(doc: dict, node_id: str) -> dict | None
# def children(doc: dict, node: dict) -> list[dict]
# def scope_nodes(doc: dict, scope: str) -> list[dict]
# def table_rows(node: dict) -> list[Tuple[int, dict]]
# ------------------------------------------------------------------

# ------------------------------------------------------------------
# Parsing helpers
# ------------------------------------------------------------------
def _parse_object_line(line: str) -> Tuple[str, str] | None:
    """
    Parse lines of the form:
      Object 0: purple metal sphere (color=purple, ...)
    Return (id, description)
    """
    m = re.match(r'^Object\s+(\d+):\s+([^\(]+)', line.strip())
    if m:
        return m.group(1), m.group(2).strip()
    return None


def _frame_from_line(line: str) -> int | None:
    m = re.match(r'^Frame\s+(\d+):', line.strip())
    return int(m.group(1)) if m else None


def _extract_collision(line: str) -> Tuple[int, str, str] | None:
    """Return (frame, id1, id2) if the line describes a collision."""
    if 'collides with' not in line.lower():
        return None
    frame = _frame_from_line(line)
    if frame is None:
        return None
    ids = re.findall(r'Object\s+(\d+)', line)
    if len(ids) >= 2:
        return frame, ids[0], ids[1]
    return None


def _extract_exit(line: str) -> Tuple[int, str] | None:
    if 'exits the scene' not in line.lower():
        return None
    frame = _frame_from_line(line)
    if frame is None:
        return None
    m = re.search(r'Object\s+(\d+)', line)
    return (frame, m.group(1)) if m else None


def _extract_initial(line: str) -> Tuple[int, str, str] | None:
    """
    Detect a line that introduces an object (either in view at start or entering).
    Returns (frame, id, kind)
    """
    frame = _frame_from_line(line)
    if frame is None:
        return None
    m = re.search(r'Object\s+(\d+)', line)
    if not m:
        return None
    obj_id = m.group(1)
    if 'in view when the video begins' in line.lower():
        kind = 'initial'
    elif 'enters the scene' in line.lower():
        kind = 'enter'
    else:
        return None
    return frame, obj_id, kind


# ------------------------------------------------------------------
# Required functions
# ------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Collect every object described in the :Objects list of the scope."""
    ents = []
    node = node_by_title(doc, f'{scope}: Objects')
    if not node:
        return ents
    for idx, line in enumerate(node.get('lines', [])):
        parsed = _parse_object_line(line)
        if parsed:
            eid, desc = parsed
            ents.append({'id': eid, 'description': desc})
    return ents


def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """Maximum frame number that appears in the scope."""
    max_f = None

    # Events (line based)
    ev_node = node_by_title(doc, f'{scope}: Events')
    if ev_node:
        for line in ev_node.get('lines', []):
            f = _frame_from_line(line)
            if f is not None:
                max_f = f if max_f is None else max(max_f, f)

    # Motion log (table)
    ml_node = node_by_title(doc, f'{scope}: Motion log')
    if ml_node and ml_node.get('kind') == 'table':
        for row_index, row in table_rows(ml_node):
            try:
                f = int(row.get('frame', '').strip())
                max_f = f if max_f is None else max(max_f, f)
            except Exception:
                continue

    return float(max_f) if max_f is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All external events that the process receives."""

    inputs = []

    # 1. Object definitions (from the Objects list)
    obj_node = node_by_title(doc, f'{scope}: Objects')
    if obj_node:
        defs_seen = set()
        for idx, line in enumerate(obj_node.get('lines', [])):
            parsed = _parse_object_line(line)
            if parsed:
                obj_id, _ = parsed
                if obj_id not in defs_seen:
                    defs_seen.add(obj_id)
                    inputs.append({
                        'id': f'input-def-{obj_id}',
                        'time': None,
                        'kind': 'definition',
                        'entities': [obj_id],
                        'fields': {},
                        'src': [[obj_node['node_id'], idx]]
                    })

    # 2. Object appearance (initial or entering)
    ev_node = node_by_title(doc, f'{scope}: Events')
    if ev_node:
        for idx, line in enumerate(ev_node.get('lines', [])):
            parsed = _extract_initial(line)
            if parsed:
                frame, obj_id, kind = parsed
                inputs.append({
                    'id': f'input-{obj_id}-{idx}',
                    'time': frame,
                    'kind': kind,
                    'entities': [obj_id],
                    'fields': {},
                    'src': [[ev_node['node_id'], idx]]
                })

    return inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All events generated by the process and any recorded results."""

    outs = []

    # 1. Collision and exit events from the Events list
    ev_node = node_by_title(doc, f'{scope}: Events')
    if ev_node:
        for idx, line in enumerate(ev_node.get('lines', [])):
            # Collision
            coll = _extract_collision(line)
            if coll:
                frame, oid1, oid2 = coll
                outs.append({
                    'time': frame,
                    'kind': 'collision',
                    'entities': [oid1, oid2],
                    'value': None,
                    'src': [[ev_node['node_id'], idx]]
                })
            # Exit
            ex = _extract_exit(line)
            if ex:
                frame, obj_id = ex
                outs.append({
                    'time': frame,
                    'kind': 'exit',
                    'entities': [obj_id],
                    'value': None,
                    'src': [[ev_node['node_id'], idx]]
                })
            # (No explicit video_end line is typically present; skip)

    # 2. Motion‑log measurements (speed)
    ml_node = node_by_title(doc, f'{scope}: Motion log')
    if ml_node and ml_node.get('kind') == 'table':
        for row_index, row in table_rows(ml_node):
            try:
                frame = int(row.get('frame', '').strip())
            except Exception:
                continue
            obj_field = row.get('object', '').strip()
            m = re.match(r'^(\d+)', obj_field)
            if not m:
                continue
            obj_id = m.group(1)
            try:
                speed = float(row.get('speed', '').strip())
            except Exception:
                continue
            outs.append({
                'time': frame,
                'kind': 'measurement',
                'entities': [obj_id],
                'value': speed,
                'src': [[ml_node['node_id'], row_index, ['frame', 'object', 'speed']]]
            })

    return outs


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Union[int, float]]:
    """
    Return a dictionary of constants defined in the scope.
    The CLEVRER document does not contain such constants, so we return empty dict.
    """
    return {}
